import java.util.*;
import java.io.*;

public class MaxFlowMaze {
    static final int MAXN = 210;
    static final int INF = 0x3f3f3f3f;

    static class MaxFlowSolver {
        int[][] cap = new int[MAXN][MAXN];
        int[][] flow = new int[MAXN][MAXN];
        int[][] adj = new int[MAXN][MAXN];
        int[] degree = new int[MAXN];
        int totalNodes, s, t;
        int[] height = new int[MAXN], countH = new int[MAXN];

        void init(int n) {
            totalNodes = n;
            for (int i = 0; i <= n; i++) {
                Arrays.fill(cap[i], 0);
                Arrays.fill(adj[i], 0);
                degree[i] = 0;
            }
            Arrays.fill(height, 0);
            Arrays.fill(countH, 0);
        }

        void addEdge(int u, int v, int c) {
            cap[u][v] += c;
            if (adj[u][v] == 0) {
                adj[u][v] = 1;
                degree[u]++;
            }
        }

        int augment(int u, int flowIn) {
            if (u == t) return flowIn;
            int totalFlow = 0;
            for (int v = 0; v < totalNodes; v++) {
                if (cap[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                    int pushed = Math.min(flowIn, cap[u][v] - flow[u][v]);
                    int pushedAmount = augment(v, pushed);
                    if (pushedAmount > 0) {
                        flow[u][v] += pushedAmount;
                        flow[v][u] -= pushedAmount;
                        totalFlow += pushedAmount;
                        flowIn -= pushedAmount;
                        if (flowIn == 0) break;
                    }
                }
            }
            if (totalFlow == 0) {
                int minH = totalNodes;
                for (int v = 0; v < totalNodes; v++) {
                    if (cap[u][v] - flow[u][v] > 0) minH = Math.min(minH, height[v]);
                }
                if (--countH[height[u]] == 0) height[s] = totalNodes;
                height[u] = minH + 1;
                countH[height[u]]++;
            }
            return totalFlow;
        }

        int maxFlow(int s_, int t_) {
            s = s_; t = t_;
            for (int i = 0; i <= totalNodes; i++) {
                Arrays.fill(flow[i], 0);
                height[i] = 0;
            }
            Arrays.fill(countH, 0);
            countH[0] = totalNodes;
            int totalFlow = 0;
            while (height[s] < totalNodes) {
                totalFlow += augment(s, INF);
            }
            return totalFlow;
        }
    }

    static class Cell {
        int r, c, d;
        Cell(int r, int c, int d) {
            this.r = r; this.c = c; this.d = d;
        }
    }

    static int n, T;
    static int startX, startY;
    static int[] dirX = {0, 0, -1, 1};
    static int[] dirY = {-1, 1, 0, 0};
    static char[][] mazeA = new char[210][210];
    static char[][] mazeB = new char[210][210];
    static int[][] distMap = new int[210][210];
    static int[][] visited = new int[210][210];
    static MaxFlowSolver solver = new MaxFlowSolver();

    static int getID(int i, int j) {
        return (i - 1) * n + j;
    }

    static boolean valid(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= n;
    }

    static void BFS1() {
        Queue<Cell> q = new LinkedList<>();
        Cell c = new Cell(startX, startY, 0);
        for (int i = 0; i < 210; i++) {
            Arrays.fill(distMap[i], Integer.MAX_VALUE);
            Arrays.fill(visited[i], 0);
        }
        visited[startX][startY] = 1;
        q.offer(c);
        while (!q.isEmpty()) {
            c = q.poll();
            distMap[c.r][c.c] = c.d;
            if (c.d > T) break;
            for (int k = 0; k < 4; k++) {
                int nx = c.r + dirX[k], ny = c.c + dirY[k];
                if (valid(nx, ny) && mazeA[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    q.offer(new Cell(nx, ny, c.d + 1));
                }
            }
        }
    }

    static void BFS2(int i, int j) {
        Queue<Cell> q = new LinkedList<>();
        for (int k = 0; k < 210; k++) {
            Arrays.fill(visited[k], 0);
        }
        visited[i][j] = 1;
        q.offer(new Cell(i, j, 0));
        while (!q.isEmpty()) {
            Cell c = q.poll();
            if (c.d > T) break;
            if (distMap[c.r][c.c] < c.d) continue;
            if ((distMap[c.r][c.c] == c.d && mazeB[c.r][c.c] < '1') || mazeB[c.r][c.c] > '9') continue;
            if (mazeB[c.r][c.c] >= '1' && mazeB[c.r][c.c] <= '9') {
                if (c.r != i || c.c != j)
                    solver.addEdge(getID(i, j), getID(c.r, c.c) + n * n, INF);
                if (distMap[c.r][c.c] == c.d) continue;
            }
            for (int k = 0; k < 4; k++) {
                int nx = c.r + dirX[k], ny = c.c + dirY[k];
                if (valid(nx, ny) && mazeA[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    q.offer(new Cell(nx, ny, c.d + 1));
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                mazeA[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                mazeB[i][j] = line.charAt(j - 1);
            }
        }
        int s = 0, e = 2 * n * n + 1;
        solver.init(e + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (mazeA[i][j] >= '1' && mazeA[i][j] <= '9') {
                    solver.addEdge(s, getID(i, j), mazeA[i][j] - '0');
                }
                if (mazeA[i][j] == 'Z') {
                    startX = i; startY = j;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                solver.addEdge(getID(i, j), getID(i, j) + n * n, INF);
                if (mazeB[i][j] >= '1' && mazeB[i][j] <= '9') {
                    solver.addEdge(getID(i, j) + n * n, e, mazeB[i][j] - '0');
                }
            }
        }
        BFS1();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (mazeA[i][j] >= '1' && mazeA[i][j] <= '9') BFS2(i, j);
            }
        }
        int res = solver.maxFlow(s, e);
        System.out.println(res);
    }
}
